public class ConsistentHashRing<T> {
    private final TreeMap<Integer, T> ring = new TreeMap<>();
    private final HashFunction hashFunction = new MurmurHash();

    public void addNode(T node) {
        int hash = hashFunction.hash(node.toString());
        ring.put(hash, node);
    }

    public T get(String key) {
        if (ring.isEmpty()) return null;
        int hash = hashFunction.hash(key);
        // Find the first node with a hash >= key hash
        Map.Entry<Integer, T> entry = ring.ceilingEntry(hash);
        // If we reach the end of the ring, wrap around to the first node
        return (entry == null) ? ring.firstEntry().getValue() : entry.getValue();
    }
}
